import{_ as a,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"20 | 大名⿍⿍的select：看我如何同时感知多个I/O事件","description":"","frontmatter":{},"headers":[{"level":2,"title":"什么是I/O多路复用","slug":"什么是i-o多路复用","link":"#什么是i-o多路复用","children":[]},{"level":2,"title":"select函数的使用方法","slug":"select函数的使用方法","link":"#select函数的使用方法","children":[]},{"level":2,"title":"程序例子","slug":"程序例子","link":"#程序例子","children":[]},{"level":2,"title":"套接字描述符就绪条件","slug":"套接字描述符就绪条件","link":"#套接字描述符就绪条件","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"网络编程实战/20-大名⿍⿍的select：看我如何同时感知多个I-O事件.md","filePath":"网络编程实战/20-大名⿍⿍的select：看我如何同时感知多个I-O事件.md","lastUpdated":1779821786000}'),l={name:"网络编程实战/20-大名⿍⿍的select：看我如何同时感知多个I-O事件.md"};function t(i,s,c,r,d,o){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_20-大名鼎鼎的select-看我如何同时感知多个i-o事件" tabindex="-1">20 | 大名⿍⿍的select：看我如何同时感知多个I/O事件 <a class="header-anchor" href="#_20-大名鼎鼎的select-看我如何同时感知多个i-o事件" aria-label="Permalink to &quot;20 | 大名⿍⿍的select：看我如何同时感知多个I/O事件&quot;">​</a></h1><p>你好，我是盛延敏，这里是网络编程实战的第20讲，欢迎回来。</p><p>这一讲是性能篇的第一讲。在性能篇里，我们将把注意力放到如何设计高并发高性能的网络服务器程序上。我希望通过这一模块的学习，让你能够掌握多路复用、异步I/O、多线程等知识，从而可以写出支持并发10K以上的高性能网络服务器程序。</p><p>还等什么呢？让我们开始吧。</p><h2 id="什么是i-o多路复用" tabindex="-1">什么是I/O多路复用 <a class="header-anchor" href="#什么是i-o多路复用" aria-label="Permalink to &quot;什么是I/O多路复用&quot;">​</a></h2><p>在 <a href="https://time.geekbang.org/column/article/126126" target="_blank" rel="noreferrer">第11讲</a> 中，我们设计了这样一个应用程序，该程序从标准输入接收数据输入，然后通过套接字发送出去，同时，该程序也通过套接字接收对方发送的数据流。</p><p>我们可以使用fgets方法等待标准输入，但是一旦这样做，就没有办法在套接字有数据的时候读出数据；我们也可以使用read方法等待套接字有数据返回，但是这样做，也没有办法在标准输入有数据的情况下，读入数据并发送给对方。</p><p>I/O多路复用的设计初衷就是解决这样的场景。我们可以把标准输入、套接字等都看做I/O的一路，多路复用的意思，就是在任何一路I/O有“事件”发生的情况下，通知应用程序去处理相应的I/O事件，这样我们的程序就变成了“多面手”，在同一时刻仿佛可以处理多个I/O事件。</p><p>像刚才的例子，使用I/O复用以后，如果标准输入有数据，立即从标准输入读入数据，通过套接字发送出去；如果套接字有数据可以读，立即可以读出数据。</p><p>select函数就是这样一种常见的I/O多路复用技术，我们将在后面继续讲解其他的多路复用技术。使用select函数，通知内核挂起进程，当一个或多个I/O事件发生后，控制权返还给应用程序，由应用程序进行I/O事件的处理。</p><p>这些I/O事件的类型非常多，比如：</p><ul><li>标准输入文件描述符准备好可以读。</li><li>监听套接字准备好，新的连接已经建立成功。</li><li>已连接套接字准备好可以写。</li><li>如果一个I/O事件等待超过了10秒，发生了超时事件。</li></ul><h2 id="select函数的使用方法" tabindex="-1">select函数的使用方法 <a class="header-anchor" href="#select函数的使用方法" aria-label="Permalink to &quot;select函数的使用方法&quot;">​</a></h2><p>select函数的使用方法有点复杂，我们先看一下它的声明：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int select(int maxfd, fd_set *readset, fd_set *writeset, fd_set *exceptset, const struct timeval *timeout);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>返回：若有就绪描述符则为其数目，若超时则为0，若出错则为-1</span></span></code></pre></div><p>在这个函数中，maxfd表示的是待测试的描述符基数，它的值是待测试的最大描述符加1。比如现在的select待测试的描述符集合是{0,1,4}，那么maxfd就是5，为啥是5，而不是4呢? 我会在下面进行解释。</p><p>紧接着的是三个描述符集合，分别是读描述符集合readset、写描述符集合writeset和异常描述符集合exceptset，这三个分别通知内核，在哪些描述符上检测数据可以读，可以写和有异常发生。</p><p>那么如何设置这些描述符集合呢？以下的宏可以帮助到我们。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void FD_ZERO(fd_set *fdset);</span></span>
<span class="line"><span>void FD_SET(int fd, fd_set *fdset);</span></span>
<span class="line"><span>void FD_CLR(int fd, fd_set *fdset);</span></span>
<span class="line"><span>int  FD_ISSET(int fd, fd_set *fdset);</span></span></code></pre></div><p>如果你刚刚入门，理解这些宏可能有些困难。没有关系，我们可以这样想象，下面一个向量代表了一个描述符集合，其中，这个向量的每个元素都是二进制数中的0或者1。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a[maxfd-1], ..., a[1], a[0]</span></span></code></pre></div><p>我们按照这样的思路来理解这些宏：</p><ul><li>FD_ZERO用来将这个向量的所有元素都设置成0；</li><li>FD_SET用来把对应套接字fd的元素，a[fd]设置成1；</li><li>FD_CLR用来把对应套接字fd的元素，a[fd]设置成0；</li><li>FD_ISSET对这个向量进行检测，判断出对应套接字的元素a[fd]是0还是1。</li></ul><p>其中0代表不需要处理，1代表需要处理。</p><p>怎么样，是不是感觉豁然开朗了？</p><p>实际上，很多系统是用一个整型数组来表示一个描述字集合的，一个32位的整型数可以表示32个描述字，例如第一个整型数表示0-31描述字，第二个整型数可以表示32-63描述字，以此类推。</p><p>这个时候再来理解为什么描述字集合{0,1,4}，对应的maxfd是5，而不是4，就比较方便了。</p><p>因为这个向量对应的是下面这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a[4],a[3],a[2],a[1],a[0]</span></span></code></pre></div><p>待测试的描述符个数显然是5， 而不是4。</p><p>三个描述符集合中的每一个都可以设置成空，这样就表示不需要内核进行相关的检测。</p><p>最后一个参数是timeval结构体时间：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct timeval {</span></span>
<span class="line"><span>  long   tv_sec; /* seconds */</span></span>
<span class="line"><span>  long   tv_usec; /* microseconds */</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>这个参数设置成不同的值，会有不同的可能：</p><p>第一个可能是设置成空(NULL)，表示如果没有I/O事件发生，则select一直等待下去。</p><p>第二个可能是设置一个非零的值，这个表示等待固定的一段时间后从select阻塞调用中返回，这在 <a href="https://time.geekbang.org/column/article/127900" target="_blank" rel="noreferrer">第12讲</a> 超时的例子里曾经使用过。</p><p>第三个可能是将tv_sec和tv_usec都设置成0，表示根本不等待，检测完毕立即返回。这种情况使用得比较少。</p><h2 id="程序例子" tabindex="-1">程序例子 <a class="header-anchor" href="#程序例子" aria-label="Permalink to &quot;程序例子&quot;">​</a></h2><p>下面是一个具体的程序例子，我们通过这个例子来理解select函数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int main(int argc, char **argv) {</span></span>
<span class="line"><span>    if (argc != 2) {</span></span>
<span class="line"><span>        error(1, 0, &quot;usage: select01 &amp;lt;IPaddress&amp;gt;&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    int socket_fd = tcp_client(argv[1], SERV_PORT);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    char recv_line[MAXLINE], send_line[MAXLINE];</span></span>
<span class="line"><span>    int n;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    fd_set readmask;</span></span>
<span class="line"><span>    fd_set allreads;</span></span>
<span class="line"><span>    FD_ZERO(&amp;allreads);</span></span>
<span class="line"><span>    FD_SET(0, &amp;allreads);</span></span>
<span class="line"><span>    FD_SET(socket_fd, &amp;allreads);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    for (;;) {</span></span>
<span class="line"><span>        readmask = allreads;</span></span>
<span class="line"><span>        int rc = select(socket_fd + 1, &amp;readmask, NULL, NULL, NULL);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        if (rc &amp;lt;= 0) {</span></span>
<span class="line"><span>            error(1, errno, &quot;select failed&quot;);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        if (FD_ISSET(socket_fd, &amp;readmask)) {</span></span>
<span class="line"><span>            n = read(socket_fd, recv_line, MAXLINE);</span></span>
<span class="line"><span>            if (n &amp;lt; 0) {</span></span>
<span class="line"><span>                error(1, errno, &quot;read error&quot;);</span></span>
<span class="line"><span>            } else if (n == 0) {</span></span>
<span class="line"><span>                error(1, 0, &quot;server terminated \\n&quot;);</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>            recv_line[n] = 0;</span></span>
<span class="line"><span>            fputs(recv_line, stdout);</span></span>
<span class="line"><span>            fputs(&quot;\\n&quot;, stdout);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        if (FD_ISSET(STDIN_FILENO, &amp;readmask)) {</span></span>
<span class="line"><span>            if (fgets(send_line, MAXLINE, stdin) != NULL) {</span></span>
<span class="line"><span>                int i = strlen(send_line);</span></span>
<span class="line"><span>                if (send_line[i - 1] == &#39;\\n&#39;) {</span></span>
<span class="line"><span>                    send_line[i - 1] = 0;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                printf(&quot;now sending %s\\n&quot;, send_line);</span></span>
<span class="line"><span>                size_t rt = write(socket_fd, send_line, strlen(send_line));</span></span>
<span class="line"><span>                if (rt &amp;lt; 0) {</span></span>
<span class="line"><span>                    error(1, errno, &quot;write failed &quot;);</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>                printf(&quot;send bytes: %zu \\n&quot;, rt);</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span></code></pre></div><p>程序的12行通过FD_ZERO初始化了一个描述符集合，这个描述符读集合是空的：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/138948/cea07eee264c1abf69c04aacfae56c68.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/138948/cea07eee264c1abf69c04aacfae56c68.png" alt=""></a></p><p>接下来程序的第13和14行，分别使用FD_SET将描述符0，即标准输入，以及连接套接字描述符3设置为待检测：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/138948/714f4fb84ab9afb39e51f6bcfc18def2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/138948/714f4fb84ab9afb39e51f6bcfc18def2.png" alt=""></a></p><p>接下来的16-51行是循环检测，这里我们没有阻塞在fgets或read调用，而是通过select来检测套接字描述字有数据可读，或者标准输入有数据可读。比如，当用户通过标准输入使得标准输入描述符可读时，返回的readmask的值为：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/138948/b90d1df438847d5e11d80485a23817bd.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/138948/b90d1df438847d5e11d80485a23817bd.png" alt=""></a></p><p>这个时候select调用返回，可以使用FD_ISSET来判断哪个描述符准备好可读了。如上图所示，这个时候是标准输入可读，37-51行程序读入后发送给对端。</p><p>如果是连接描述字准备好可读了，第24行判断为真，使用read将套接字数据读出。</p><p>我们需要注意的是，这个程序的17-18行非常重要，初学者很容易在这里掉坑里去。</p><p>第17行是每次测试完之后，重新设置待测试的描述符集合。你可以看到上面的例子，在select测试之前的数据是{0,3}，select测试之后就变成了{0}。</p><p>这是因为select调用每次完成测试之后，内核都会修改描述符集合，通过修改完的描述符集合来和应用程序交互，应用程序使用FD_ISSET来对每个描述符进行判断，从而知道什么样的事件发生。</p><p>第18行则是使用socket_fd+1来表示待测试的描述符基数。切记需要+1。</p><h2 id="套接字描述符就绪条件" tabindex="-1">套接字描述符就绪条件 <a class="header-anchor" href="#套接字描述符就绪条件" aria-label="Permalink to &quot;套接字描述符就绪条件&quot;">​</a></h2><p>当我们说select测试返回，某个套接字准备好可读，表示什么样的事件发生呢？</p><p>第一种情况是套接字接收缓冲区有数据可以读，如果我们使用read函数去执行读操作，肯定不会被阻塞，而是会直接读到这部分数据。</p><p>第二种情况是对方发送了FIN，使用read函数执行读操作，不会被阻塞，直接返回0。</p><p>第三种情况是针对一个监听套接字而言的，有已经完成的连接建立，此时使用accept函数去执行不会阻塞，直接返回已经完成的连接。</p><p>第四种情况是套接字有错误待处理，使用read函数去执行读操作，不阻塞，且返回-1。</p><p>总结成一句话就是，内核通知我们套接字有数据可以读了，使用read函数不会阻塞。</p><p>不知道你是不是和我一样，刚开始理解某个套接字可写的时候，会有一个错觉，总是从应用程序角度出发去理解套接字可写，我开始是这样想的，当应用程序完成相应的计算，有数据准备发送给对端了，可以往套接字写，对应的就是套接字可写。</p><p>其实这个理解是非常不正确的，select检测套接字可写， <strong>完全是基于套接字本身的特性来说</strong> 的，具体来说有以下几种情况。</p><p>第一种是套接字发送缓冲区足够大，如果我们使用阻塞套接字进行write操作，将不会被阻塞，直接返回。</p><p>第二种是连接的写半边已经关闭，如果继续进行写操作将会产生SIGPIPE信号。</p><p>第三种是套接字上有错误待处理，使用write函数去执行写操作，不阻塞，且返回-1。</p><p>总结成一句话就是，内核通知我们套接字可以往里写了，使用write函数就不会阻塞。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我讲了select函数的使用。select函数提供了最基本的I/O多路复用方法，在使用select时，我们需要建立两个重要的认识：</p><ul><li>描述符基数是当前最大描述符+1；</li><li>每次select调用完成之后，记得要重置待测试集合。</li></ul><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>和往常一样，给你布置两道思考题：</p><p>第一道， select可以对诸如UNIX管道(pipe)这样的描述字进行检测么？如果可以，检测的就绪条件是什么呢？</p><p>第二道，根据我们前面的描述，一个描述符集合哪些描述符被设置为1，需要进行检测是完全可以知道的，你认为select函数里一定需要传入描述字基数这个值么？请你分析一下这样设计的目的又是什么呢？</p><p>欢迎你在评论区写下你的思考，也欢迎把这篇文章分享给你的朋友或者同事，一起交流一下。</p>`,73)])])}const _=a(l,[["render",t]]);export{u as __pageData,_ as default};
